package glitch

import data.glitch_lib

download_types := {"get_url", "remote_file", "archive", "maven_artifact", "fetch", "download"}

integrity_names := {"checksum", "sha256", "sha512", "sha384", "sha224", "sha1", "md5", "hash", "integrity"}

has_integrity_attr(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == integrity_names[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    node.type == download_types[_]
    not has_integrity_attr(node)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Remote file downloads should include a checksum or hash to verify data integrity during transmission. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [_, obj])
    obj.key.ir_type == "String"
    obj.key.value == "gpgcheck"
    obj.value.ir_type == "Integer"
    obj.value.value == 0

    result := {
        "type": "sec_no_int_check",
        "element": obj.key,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - GPG check is disabled, removing integrity verification for package and repository downloads. (CWE-353)"
    }
}

