package glitch

import data.glitch_lib

integrity_keywords := {"checksum", "sha256", "sha512", "sha384", "sha224", "sha1", "md5sum", "sha256sum", "integrity", "verify", "checksum_url"}

has_integrity_attr(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    keyword := integrity_keywords[_]
    contains(attr.name, keyword)
}

has_integrity_in_code(node) {
    regex.match("(?i).*(checksum|sha256|sha512|sha384|sha224|sha1|md5sum|sha256sum|integrity|verify).*", node.code)
}

has_url_in_code(node) {
    regex.match("(?i).*(https?://|ftp://).*", node.code)
}

Glitch_Analysis[result] {
    walk(input, [_, ub])
    ub.ir_type == "UnitBlock"
    ub.path != ""
    walk(ub, [_, hash_node])
    hash_node.ir_type == "Hash"
    entry := hash_node.value[_]
    entry.key.ir_type == "String"
    entry.key.value == "gpgcheck"
    entry.value.ir_type == "Integer"
    entry.value.value == 0

    result := {
        "type": "sec_no_int_check",
        "element": entry.value,
        "path": ub.path,
        "description": "Missing Support for Integrity Check - GPG check is disabled, removing integrity verification for packages. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    walk(input, [_, ub])
    ub.ir_type == "UnitBlock"
    ub.path != ""
    walk(ub, [_, node])
    node.ir_type == "AtomicUnit"
    has_url_in_code(node)
    not has_integrity_attr(node)
    not has_integrity_in_code(node)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": ub.path,
        "description": "Missing Support for Integrity Check - Remote file downloads should include a checksum or hash to verify data integrity during transmission. (CWE-353)"
    }
}

